'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var parseJSON = require( '@stdlib/utils/parse-json' );
var Number = require( '@stdlib/number/ctor' );
var trim = require( '@stdlib/string/base/trim' );
var format = require( '@stdlib/string/format' );


// FUNCTIONS //

/**
* Transforms a request body to a boolean.
*
* @private
* @param {string} value - raw request body
* @throws {TypeError} unable to parse as a boolean
* @returns {*} transformed value
*/
function toBoolean( value ) {
	var v = trim( value );
	if ( v === 'true' ) {
		return true;
	}
	if ( v === 'false' ) {
		return false;
	}
	throw new TypeError( format( 'invalid argument. Must provide a boolean string. Value: `%s`.', value ) );
}

/**
* Transforms a request body to either a boolean or a number.
*
* @private
* @param {string} value - raw request body
* @throws {TypeError} unable to parse as a boolean or a number
* @returns {(boolean|number)} transformed value
*/
function toBooleanOrNumber( value ) {
	var n;
	var v;

	v = trim( value );
	if ( v === '' || v === 'false' ) {
		return false;
	}
	if ( v === 'true' ) {
		return true;
	}
	n = Number( v );
	if ( isnan( n ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a number or a boolean. Value: `%s`.', value ) );
	}
	return n;
}

/**
* Transforms a request body to either a boolean or a string.
*
* @private
* @param {string} value - raw request body
* @returns {(boolean|string)} transformed value
*/
function toBooleanOrString( value ) {
	var v;

	v = trim( value );
	if ( v === '' || v === 'false' ) {
		return false;
	}
	if ( v === 'true' ) {
		return true;
	}
	return v;
}

/**
* Transforms a request body to an integer.
*
* @private
* @param {string} value - raw request body
* @throws {TypeError} unable to parse as an integer
* @returns {*} transformed value
*/
function toInteger( value ) {
	var v = parseInt( value, 10 );
	if ( isnan( v ) ) {
		throw new TypeError( format( 'invalid argument. Must provide an integer string. Value: `%s`.', value ) );
	}
	return v;
}

/**
* Transforms a request body to a JSON object.
*
* @private
* @param {string} value - raw request body
* @throws {Error} unexpected error
* @returns {*} transformed value
*/
function toJSON( value ) {
	value = parseJSON( value );
	if ( value instanceof Error ) {
		throw value;
	}
	return value;
}

/**
* Transforms a request body to a number.
*
* @private
* @param {string} value - raw request body
* @throws {TypeError} unable to parse as a number
* @returns {*} transformed value
*/
function toNumber( value ) {
	var n = Number( value );
	if ( isnan( n ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a number string. Value: `%s`.', value ) );
	}
	return n;
}

/**
* Transforms a request body to either a number or `undefined`.
*
* @private
* @param {string} value - raw request body
* @throws {TypeError} unable to parse as a number
* @returns {*} transformed value
*/
function toNumberOrUndefined( value ) {
	var n;
	var v;

	v = trim( value );
	if ( v === '' ) {
		return void 0;
	}
	n = Number( v );
	if ( isnan( n ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a number string. Value: `%s`.', value ) );
	}
	return n;
}

/**
* Transforms a request body containing comma-separated values to an array of integers.
*
* @private
* @param {string} value - raw request body
* @throws {TypeError} must provide a comma-separated list of integers
* @returns {Array<integer>} transformed value
*/
function toIntegerArray( value ) {
	var out;
	var tmp;
	var v;
	var i;

	v = trim( value );
	if ( v === '' ) {
		return [];
	}
	tmp = v.split( /\s*,\s*/ );
	out = [];
	for ( i = 0; i < tmp.length; i++ ) {
		v = parseInt( tmp[ i ], 10 );
		if ( isnan( v ) ) {
			throw new TypeError( format( 'invalid argument. Must provide a comma-separated list of integers. Value: `%s`.', value ) );
		}
		out.push( v );
	}
	return out;
}

/**
* Transforms a request body to a valid font weight value.
*
* @private
* @param {string} value - raw request body
* @returns {(number|string|void)} transformed value
*/
function toFontWeight( value ) {
	var n;
	var v;

	v = trim( value );
	if ( v === '' ) {
		return void 0;
	}
	n = Number( v );
	if ( !isnan( n ) ) {
		return n;
	}
	return v;
}

/**
* Transforms a request body to a valid tick count value.
*
* @private
* @param {string} value - raw request body
* @returns {(number|string|Object|void)} transformed value
*/
function toTickCount( value ) {
	var parts;
	var n;
	var v;

	v = trim( value );
	if ( v === '' ) {
		return void 0;
	}
	n = Number( v );
	if ( !isnan( n ) ) {
		return n;
	}
	if ( v.indexOf( ',' ) !== -1 ) {
		parts = v.split( /\s*,\s*/ );
		return {
			'interval': parts[0],
			'step': parseInt( parts[1], 10 )
		};
	}
	return v;
}

/**
* Transforms a request body to either a string or `undefined`.
*
* @private
* @param {string} value - raw request body
* @returns {string} transformed value
*/
function empty2undefined( value ) {
	return ( value === '' ) ? void 0 : value;
}


// MAIN //

/**
* Object containing request body transforms.
*
* @private
* @name transforms
* @type {Object}
*/
var transforms = { // eslint-disable-line vars-on-top
	'toBoolean': toBoolean,
	'toBooleanOrNumber': toBooleanOrNumber,
	'toBooleanOrString': toBooleanOrString,
	'toInteger': toInteger,
	'toJSON': toJSON,
	'toNumber': toNumber,
	'toNumberOrUndefined': toNumberOrUndefined,
	'toIntegerArray': toIntegerArray,
	'toTickCount': toTickCount,
	'toFontWeight': toFontWeight,
	'empty2undefined': empty2undefined
};


// EXPORTS //

module.exports = transforms;
